  --color-primary:     #5b6cf9;
  --color-primary-dark:#4757e6;
  --color-text:        #1a1d2e;
  --color-text-muted:  #6b7280;
  --color-check-bg:    #eef0fe;
  --color-check-hover: #e0e3fd;
  --color-success:     #16a34a;
  --color-error:       #dc2626;
  --color-error-bg:    #fef2f2;
  --radius-sm:         6px;
  --radius-md:         12px;
  --radius-lg:         16px;
  --shadow-card:       0 1px 3px rgba(0,0,0,.07), 0 4px 16px rgba(0,0,0,.06);
  --shadow-card-hover: 0 4px 20px rgba(91,108,249,.15);
  --font: 'Inter', system-ui, -apple-system, sans-serif;
}

body {
  font-family: var(--font);
  background: var(--color-bg);
  color: var(--color-text);
  min-height: 100vh;
  padding: 2rem 1rem 4rem;
  line-height: 1.5;
}

/* ── Page shell ───────────────────────────────────── */
.page-header {
  text-align: center;
  margin-bottom: 2.5rem;
}

.page-header__badge {
  display: inline-flex;
  align-items: center;
  gap: .375rem;
  background: var(--color-check-bg);
  color: var(--color-primary);
  font-size: .75rem;
  font-weight: 600;
  letter-spacing: .06em;
  text-transform: uppercase;
  padding: .3rem .75rem;
  border-radius: 99px;
  margin-bottom: .875rem;
}

.page-header__title {
  font-size: clamp(1.75rem, 4vw, 2.5rem);
  font-weight: 800;
  letter-spacing: -.02em;
  color: var(--color-text);
  margin-bottom: .5rem;
}

.page-header__subtitle {
  font-size: 1rem;
  color: var(--color-text-muted);
  max-width: 42ch;
  margin-inline: auto;
}

/* ── Quiz container ───────────────────────────────── */
.quiz {
  max-width: 640px;
  margin-inline: auto;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

/* ── form-field (question card) ──────────────────── */
.form-field {
  background: var(--color-surface);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 1.5rem 1.75rem;
  box-shadow: var(--shadow-card);
  transition: box-shadow .2s, border-color .2s;
}

.form-field:focus-within {
  border-color: var(--color-border-focus);
  box-shadow: var(--shadow-card-hover);
}

/* fieldset strips default styling */
.form-field fieldset {
  border: none;
}

.question-header {
  display: flex;
  align-items: flex-start;
  gap: .625rem;
  margin-bottom: .5rem;
}

.question-number {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.625rem;
  height: 1.625rem;
  border-radius: 50%;
  background: var(--color-check-bg);
  color: var(--color-primary);
  font-size: .75rem;
  font-weight: 700;
  margin-top: .1rem;
}

.question-legend {
  font-size: 1rem;
  font-weight: 700;
  color: var(--color-text);
  line-height: 1.4;
}

/* help text */
.help-text {
  font-size: .8125rem;
  color: var(--color-text-muted);
  margin-bottom: 1rem;
  padding-left: 2.25rem; /* align with legend text */
}

/* validation error */
.field-error {
  display: none;
  font-size: .8125rem;
  color: var(--color-error);
  margin-top: .625rem;
  padding: .5rem .75rem;
  background: var(--color-error-bg);
  border-radius: var(--radius-sm);
}

.form-field.is-invalid .field-error {
  display: flex;
  align-items: center;
  gap: .375rem;
}

/* ── Checkbox options ─────────────────────────────── */
.options-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: .5rem;
  margin-top: .75rem;
}

.option-item {
  display: flex;
}

.option-label {
  display: flex;
  align-items: center;
  gap: .75rem;
  width: 100%;
  padding: .6875rem .875rem;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background .15s, border-color .15s;
  font-size: .9375rem;
  user-select: none;
}

.option-label:hover {
  background: var(--color-check-hover);
  border-color: #c7ccf9;
}

/* custom checkbox box */
.option-label__box {
  flex-shrink: 0;
  width: 1.125rem;
  height: 1.125rem;
  border: 1.5px solid #c8ccd8;
  border-radius: 4px;
  background: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background .15s, border-color .15s;
}

/* real checkbox (visually hidden but accessible) */
.option-checkbox {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
  pointer-events: none;
}

.option-checkbox:checked + .option-label {
  background: var(--color-check-bg);
  border-color: var(--color-primary);
}

.option-checkbox:checked + .option-label .option-label__box {
  background: var(--color-primary);
  border-color: var(--color-primary);
}

.option-checkbox:checked + .option-label .option-label__box::after {
  content: '';
  display: block;
  width: .35rem;
  height: .6rem;
  border: 2px solid #fff;
  border-top: none;
  border-left: none;
  transform: rotate(45deg) translate(-1px, -1px);
}

/* keyboard focus ring on the label */
.option-checkbox:focus-visible + .option-label {
  outline: 3px solid var(--color-primary);
  outline-offset: 2px;
}

/* ── Submit area ──────────────────────────────────── */
.quiz-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: .75rem;
  margin-top: .5rem;
}

.progress-text {
  font-size: .8125rem;
  color: var(--color-text-muted);
}

.btn-submit {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  background: var(--color-primary);
  color: #fff;
  font-family: var(--font);
  font-size: .9375rem;
  font-weight: 600;
  padding: .75rem 1.5rem;
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background .15s, transform .1s, box-shadow .15s;
  box-shadow: 0 2px 8px rgba(91,108,249,.35);
}

.btn-submit:hover {
  background: var(--color-primary-dark);
  box-shadow: 0 4px 14px rgba(91,108,249,.45);
}

.btn-submit:active { transform: scale(.98); }

.btn-submit:focus-visible {
  outline: 3px solid var(--color-primary);
  outline-offset: 3px;
}

/* ── Result banner ────────────────────────────────── */
.result-banner {
  display: none;
  background: var(--color-surface);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 1.75rem;
  box-shadow: var(--shadow-card);
  text-align: center;
}

.result-banner.is-visible { display: block; }

