  font-size: 1.0625rem;
  font-weight: 600;
  margin-top: .25rem;
  color: var(--color-text);
}

.result-banner__msg {
  font-size: .9375rem;
  color: var(--color-text-muted);
  margin-top: .375rem;
}

.btn-retry {
  display: inline-flex;
  align-items: center;
  gap: .375rem;
  margin-top: 1.25rem;
  background: transparent;
  color: var(--color-primary);
  font-family: var(--font);
  font-size: .9375rem;
  font-weight: 600;
  padding: .6rem 1.25rem;
  border: 1.5px solid var(--color-primary);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background .15s;
}

.btn-retry:hover { background: var(--color-check-bg); }

.btn-retry:focus-visible {
  outline: 3px solid var(--color-primary);
  outline-offset: 2px;
}

