  background: #f0fdf4;
  border-color: var(--color-success);
}

.form-field.show-result .option-checkbox:checked + .option-label.is-correct .option-label__box {
  background: var(--color-success);
  border-color: var(--color-success);
}

.form-field.show-result .option-checkbox:checked + .option-label.is-wrong {
  background: var(--color-error-bg);
  border-color: var(--color-error);
}

.form-field.show-result .option-checkbox:checked + .option-label.is-wrong .option-label__box {
  background: var(--color-error);
  border-color: var(--color-error);
}

.form-field.show-result .option-label.is-correct-missed {
  background: #f0fdf4;
  border-color: var(--color-success);
  opacity: .75;
}

/* ── Reflow @ 320 px ──────────────────────────────── */
@media (max-width: 480px) {
  .form-field { padding: 1.25rem 1rem; }
  .quiz-footer { flex-direction: column; align-items: stretch; }
  .btn-submit { justify-content: center; }
}
