+      { id: 'q2-d', text: 'PHP',        correct: false },
+    ],
+  },
+  {
+    id: 'q3',
+    text: 'Which of the following languages were created at Google?',
+    options: [
+      { id: 'q3-a', text: 'Go',     correct: true  },
+      { id: 'q3-b', text: 'Dart',   correct: true  },
+      { id: 'q3-c', text: 'Swift',  correct: false },
+      { id: 'q3-d', text: 'Kotlin', correct: false },
+    ],
+  },
+];
+
+/** Helpers -------------------------------------------------------------- */
+function el(tag, attrs = {}, ...children) {
+  const node = document.createElement(tag);
+  for (const [k, v] of Object.entries(attrs)) {
+    if (k === 'className') node.className = v;
+    else if (k === 'htmlFor') node.htmlFor = v;
+    else node.setAttribute(k, v);
+  }
+  for (const child of children.flat()) {
+    if (child == null) continue;
+    node.append(typeof child === 'string' ? document.createTextNode(child) : child);
+  }
+  return node;
+}
+
+/** CheckboxOption component -------------------------------------------- */
+function CheckboxOption({ option, questionId }) {
+  const inputId = option.id;
+
+  const labelBox = el('span', { className: 'option-label__box', 'aria-hidden': 'true' });
+  const labelText = el('span', {}, option.text);
+
+  const label = el('label', {
+    className: 'option-label',
+    htmlFor: inputId,
+    'data-correct': String(option.correct),
+  }, labelBox, labelText);
+
+  const input = el('input', {
+    type: 'checkbox',
+    className: 'option-checkbox',
+    id: inputId,
+    name: questionId,
+    value: option.id,
+  });
+
+  const wrapper = el('li', { className: 'option-item' }, input, label);
+  return wrapper;
+}
+
+/** QuestionCard component ---------------------------------------------- */
+function QuestionCard({ question, index }) {
+  const legendId    = `${question.id}-legend`;
+  const helpId      = question.help ? `${question.id}-help` : null;
+  const errorId     = `${question.id}-error`;
+  const optionsId   = `${question.id}-options`;
+
+  // Number badge
+  const numberBadge = el('span', { className: 'question-number', 'aria-hidden': 'true' }, String(index + 1));
+
+  // Legend text
+  const legend = el('legend', { className: 'question-legend', id: legendId });
+  legend.append(numberBadge, ` ${question.text}`);
+
+  // Help text (only for question 1)
+  const helpNode = question.help
+    ? el('p', { className: 'help-text', id: helpId }, question.help)
+    : null;
+
+  // Options list
+  const optionItems = question.options.map(opt => CheckboxOption({ option: opt, questionId: question.id }));
+  const optionsList = el('ul', { className: 'options-list', id: optionsId }, ...optionItems);
+
+  // Build fieldset describedby
+  const describedBy = [helpId, errorId].filter(Boolean).join(' ');
+
+  const fieldset = el('fieldset', {
+    'aria-describedby': describedBy,
+  }, legend, helpNode, optionsList);
+
+  // Error message (hidden until validation)
+  const errorMsg = el('p', {
+    className: 'field-error',
+    id: errorId,
+    role: 'alert',
+  }, '⚠ Please select at least one answer.');
+
+  const card = el('div', { className: 'form-field', id: question.id }, fieldset, errorMsg);
+  return card;
+}
+
+/** ResultBanner component ---------------------------------------------- */
+function ResultBanner() {
+  const scoreEl  = el('p', { className: 'result-banner__score' }, '');
+  const labelEl  = el('p', { className: 'result-banner__label' }, '');
+  const msgEl    = el('p', { className: 'result-banner__msg'   }, '');
+  const retryBtn = el('button', { className: 'btn-retry', type: 'button' }, '↺ Try Again');
+
+  const banner = el('div', {
+    className: 'result-banner',
+    role: 'region',
+    'aria-label': 'Quiz results',
+    'aria-live': 'polite',
+  }, scoreEl, labelEl, msgEl, retryBtn);
+
+  function show(correct, total) {
+    const pct = Math.round((correct / total) * 100);
+    scoreEl.textContent = `${correct} / ${total}`;
+    labelEl.textContent = pct === 100
+      ? '🏆 Perfect score!'
+      : pct >= 66
+        ? '✅ Well done!'
+        : pct >= 33
+          ? '📚 Keep studying!'
+          : '💡 Room to grow!';
+    msgEl.textContent = `You answered ${correct} question${correct !== 1 ? 's' : ''} correctly (${pct}%).`;
+    banner.classList.add('is-visible');
+    banner.focus();
+  }
+
+  function hide() {
+    banner.classList.remove('is-visible');
+  }
+
+  banner.tabIndex = -1; // programmatic focus target only
+  return { node: banner, show, hide, retryBtn };
+}
+
+/** QuizApp component ---------------------------------------------------- */
+function QuizApp(questions) {
+  // Build question cards
+  const cards = questions.map((q, i) => QuestionCard({ question: q, index: i }));
+
+  // Footer
+  const progressText = el('p', {
+    className: 'progress-text',
+    'aria-live': 'polite',
+  }, `${questions.length} questions · select all that apply`);
+
+  const submitBtn = el('button', {
+    className: 'btn-submit',
+    type: 'submit',
+  }, 'Submit Quiz →');
+
+  const footer = el('div', { className: 'quiz-footer' }, progressText, submitBtn);
+
+  const form = el('form', {
+    className: 'quiz',
+    noValidate: '',
+    'aria-label': 'Computer languages quiz',
+  }, ...cards, footer);
+
+  // Result banner
+  const result = ResultBanner();
+  form.append(result.node);
+
+  // ── Validation & scoring ──────────────────────────────────────────────
+  function validate() {
+    let firstInvalid = null;
+    let valid = true;
+
+    for (const q of questions) {
+      const card = document.getElementById(q.id);
+      const checked = card.querySelectorAll('input[type="checkbox"]:checked');
+
+      if (checked.length === 0) {
+        card.classList.add('is-invalid');
+        if (!firstInvalid) firstInvalid = card;
+        valid = false;
+      } else {
+        card.classList.remove('is-invalid');
+      }
+    }
+
+    if (firstInvalid) {
+      // Move focus to first invalid field's first checkbox
+      firstInvalid.querySelector('input[type="checkbox"]').focus();
+    }
+    return valid;
+  }
+
+  function score() {
+    let correct = 0;
+
+    for (const q of questions) {
+      const card = document.getElementById(q.id);
+      card.classList.add('show-result');
+      card.querySelectorAll('input[type="checkbox"]').forEach(cb => (cb.disabled = true));
+
+      // Annotate labels
+      const checked = new Set([...card.querySelectorAll('input:checked')].map(i => i.value));
+      const correctIds = new Set(q.options.filter(o => o.correct).map(o => o.id));
+
+      // Is the full set correct?
+      const fullMatch =
+        checked.size === correctIds.size &&
+        [...checked].every(id => correctIds.has(id));
+      if (fullMatch) correct++;
+
+      // Mark each label
+      for (const opt of q.options) {
+        const label = card.querySelector(`label[for="${opt.id}"]`);
+        if (!label) continue;
+        if (opt.correct && checked.has(opt.id)) {
+          label.classList.add('is-correct');
+        } else if (!opt.correct && checked.has(opt.id)) {
+          label.classList.add('is-wrong');
+        } else if (opt.correct && !checked.has(opt.id)) {
+          label.classList.add('is-correct-missed');
+        }
+      }
+    }
+
+    submitBtn.disabled = true;
+    result.show(correct, questions.length);
+  }
+
+  // ── Retry ─────────────────────────────────────────────────────────────
+  result.retryBtn.addEventListener('click', () => {
+    for (const q of questions) {
+      const card = document.getElementById(q.id);
+      card.classList.remove('is-invalid', 'show-result');
+      card.querySelectorAll('input[type="checkbox"]').forEach(cb => {
+        cb.checked  = false;
+        cb.disabled = false;
+      });
+      card.querySelectorAll('.option-label').forEach(l =>
+        l.classList.remove('is-correct', 'is-wrong', 'is-correct-missed')
+      );
+    }
+    submitBtn.disabled = false;
+    result.hide();
+    // Return focus to top of quiz
+    form.querySelector('input[type="checkbox"]').focus();
+  });
+
+  // ── Submit ─────────────────────────────────────────────────────────────
+  form.addEventListener('submit', e => {
+    e.preventDefault();
+    if (validate()) score();
+  });
+
+  // ── Live progress update ───────────────────────────────────────────────
+  form.addEventListener('change', () => {
+    const answered = questions.filter(q => {
+      const card = document.getElementById(q.id);
+      return card.querySelectorAll('input:checked').length > 0;
+    }).length;
+    progressText.textContent = answered === questions.length
+      ? 'All questions answered — ready to submit!'
+      : `${answered} of ${questions.length} answered`;
+
+    // Clear invalid state when user makes a selection
+    for (const q of questions) {
+      const card = document.getElementById(q.id);
+      if (card.querySelectorAll('input:checked').length > 0) {
+        card.classList.remove('is-invalid');
+      }
+    }
+  });
+
+  return form;
+}
+
+/** Boot ----------------------------------------------------------------- */
+document.addEventListener('DOMContentLoaded', () => {
+  const mount = document.getElementById('app');
+  mount.append(QuizApp(QUESTIONS));
+});
+
')

